package com.inventra.backend.service; import com.inventra.backend.dto.*; import com.inventra.backend.model.*; import com.inventra.backend.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*; @Service public class ReturnService {private final ReturnRepository rr;private final OrderRepository or;private final InventoryCoreService inv;public ReturnService(ReturnRepository r,OrderRepository o,InventoryCoreService i){rr=r;or=o;inv=i;}public ReturnRecord request(ReturnRequest r){Order o=or.findById(r.orderId()).orElseThrow(()->new IllegalArgumentException("Order not found"));if(o.getStatus()!=OrderStatus.FULFILLED)throw new IllegalStateException("Only fulfilled orders can be returned");boolean valid=o.getItems().stream().anyMatch(x->x.getProductId().equals(r.productId())&&x.getQuantity()>=r.quantity());if(!valid)throw new IllegalArgumentException("Return quantity exceeds ordered quantity");ReturnRecord x=new ReturnRecord();x.setOrderId(r.orderId());x.setWarehouseId(r.warehouseId());x.setProductId(r.productId());x.setQuantity(r.quantity());x.setReason(r.reason());return rr.save(x);}public ReturnRecord accept(String id){ReturnRecord x=rr.findById(id).orElseThrow(()->new IllegalArgumentException("Return not found"));if(x.getStatus()!=ReturnStatus.REQUESTED)throw new IllegalStateException("Return is not pending");inv.returnStock(x.getWarehouseId(),x.getProductId(),x.getQuantity(),x.getId());x.setStatus(ReturnStatus.COMPLETED);x.setCompletedAt(LocalDateTime.now());return rr.save(x);}public ReturnRecord reject(String id){ReturnRecord x=rr.findById(id).orElseThrow(()->new IllegalArgumentException("Return not found"));x.setStatus(ReturnStatus.REJECTED);return rr.save(x);}public List<ReturnRecord> all(){return rr.findAllByOrderByCreatedAtDesc();}}
